  g jsonb; p jsonb; ev int; gid int; cid int; hid int; vid int; cur_head int;
  made int := 0;
begin
  if exists (select 1 from public.events where name = 'زيارة مارس 2025') then
    raise notice 'المناسبة موجودة مسبقاً — لم يتم أي إدخال'; return;
  end if;
  insert into public.countries (name, dial_code) values ('عُمان', '+968') on conflict (name) do nothing;
  insert into public.events (name, start_date, end_date, description, expected_visitors)
    values ('زيارة مارس 2025', '2025-03-20', '2025-03-26', 'مستورد من كشف الوصول (رحلات الذهاب). تاريخ المغادرة غير مذكور في الكشف.', 173) returning id into ev;
  for g in select * from jsonb_array_elements(d) loop
    select id into cid from public.countries where name = g ->> 'country';
    insert into public.groups_ (event_id, name, country_id, members_count, arrival_date, notes, created_by)
      values (ev, 'المجموعة ' || (g ->> 'n') || ' - ' || (g ->> 'city'), cid, (g ->> 'total')::int, g ->> 'date',
        trim(both ' ' from concat_ws(E'\n',
          nullif(concat_ws(' | ', nullif(g ->> 'airport', ''), nullif(g ->> 'airline', ''), nullif(g ->> 'flight', ''), nullif('الوصول ' || (g ->> 'time'), 'الوصول ')), ''),
          'الإجمالي ' || (g ->> 'total') || ' (' || (g ->> 'adults') || ' بالغين - ' || (g ->> 'children') || ' أطفال)',
          nullif(g ->> 'note', ''))), 'import')
      returning id into gid;
    cur_head := null;
    for p in select * from jsonb_array_elements(g -> 'people') loop
      insert into public.visitors (event_id, full_name, name_norm, country_id, category, head_id, group_id, relation, arrival_date, arrival_time, flight_no, airline, airport, notes, created_by, updated_by)
      values (ev, p ->> 'name', gk.norm_name(p ->> 'name'), cid,
        case p ->> 'kind' when 'h' then 'family_head' when 'm' then 'family_member' else 'group_member' end,
        case when p ->> 'kind' = 'm' then cur_head end,
        case when p ->> 'kind' = 'i' then gid end,
        case when p ->> 'kind' = 'm' then 'تابع' else '' end,
        g ->> 'date', g ->> 'time', g ->> 'flight', g ->> 'airline', g ->> 'airport',
        concat_ws(' - ', 'المجموعة ' || (g ->> 'n') || ' (' || (g ->> 'city') || ')', nullif(p ->> 'note', '')), 'import', 'import')
      returning id into vid;
      if p ->> 'kind' = 'h' then cur_head := vid; end if;
      made := made + 1;
    end loop;
  end loop;
  raise notice 'تم: مناسبة زيارة مارس 2025 + 18 مجموعة + % زائراً مسمّى', made;
end $imp$;

select e.name, (select count(*) from public.groups_ where event_id = e.id) as groups,
       (select count(*) from public.visitors where event_id = e.id) as visitors
from public.events e where e.name = 'زيارة مارس 2025';
